void check(bool ok,const char* m){if(!ok)throw std::runtime_error(m);}
double magnitude(const std::vector<float>& x,int start,int count,double hz){double re=0,im=0;for(int i=0;i<count;++i){double a=6.283185307179586*hz*i/48000;re+=x[start+i]*std::cos(a);im+=x[start+i]*std::sin(a);}return 2*std::sqrt(re*re+im*im)/count;}
int main(){try{
 {fm::DelayEngine e;e.prepare(48000);fm::Settings s;s.mode=0;s.mix=1;s.timeMs=50;s.analog=1;s.feedback=s.duck=s.diffusion=0;s.hp=20;s.lp=20000;std::vector<float> in(24000),l(in.size()),r(in.size());for(size_t i=0;i<in.size();++i)in[i]=l[i]=r[i]=.2f*std::sin(i*.137)+.07f*std::sin(i*.431);e.process(l.data(),r.data(),int(l.size()),s);float error=0;for(int i=2400;i<int(l.size());++i)error=std::max(error,std::abs(l[i]-in[i-2400]));check(error<1e-5,"Clean must be an uncolored delayed copy with filters open");std::cout<<"Clean maximum error: "<<error<<'\n';}
 double tilt[4];for(int mode=0;mode<4;++mode){fm::DelayEngine e;e.prepare(48000);fm::Settings s;s.mode=mode;s.mix=1;s.timeMs=50;s.analog=.6f;s.feedback=s.duck=s.diffusion=0;s.hp=20;s.lp=20000;std::vector<float> l(48000),r(l.size());for(size_t i=0;i<l.size();++i){l[i]=.1f*std::sin(i*6.283185307179586*250/48000);r[i]=.1f*std::sin(i*6.283185307179586*8000/48000);}e.process(l.data(),r.data(),int(l.size()),s);double low=0,high=0;for(int i=12000;i<48000;++i){low+=l[i]*l[i];high+=r[i]*r[i];}tilt[mode]=std::sqrt(low/high);std::cout<<"Mode "<<mode<<" 250Hz/8kHz ratio: "<<tilt[mode]<<'\n';}check(tilt[0]<1.02&&tilt[1]>tilt[0]*2&&tilt[2]>tilt[1]*1.3&&tilt[3]>tilt[2]*1.3,"Clean/Tape/Analog/Dark must have ordered distinct bandwidths");
 {fm::AnalogColour processor;processor.prepare();std::vector<float> raw(96000),filtered(raw.size());for(int i=0;i<96000;++i){float x=.7f*std::sin(i*6.283185307179586*14000/48000);raw[i]=std::tanh(x*4)/4;filtered[i]=processor.process(x,4,0,1);}double before=magnitude(raw,48000,48000,6000),after=magnitude(filtered,48000,48000,6000);std::cout<<"Folded 6kHz harmonic, before/4x: "<<before<<" / "<<after<<'\n';check(after<before*.05,"oversampling should reduce folded nonlinear harmonics by more than 26dB");check(magnitude(filtered,48000,48000,14000)>.1,"oversampling must retain fundamental");}
 for(float amount:{0.f,.5f,1.f}){fm::DelayEngine e;e.prepare(48000);fm::Settings s;s.mode=0;s.mix=1;s.timeMs=100;s.feedback=.4f;s.duck=amount;s.duckThreshold=-36;s.analog=s.diffusion=0;s.hp=20;s.lp=20000;float l[256],r[256];for(int block=0;block<200;++block){for(int i=0;i<256;++i)l[i]=r[i]=.08923085f*std::sin((block*256+i)*6.283185307179586*1000/48000);e.process(l,r,256,s);}float reduction=e.getDuckReductionDb();std::cout<<"Ducking "<<amount<<" reduction: "<<reduction<<" dB\n";check(std::abs(reduction-18*amount)<.5,"duck amount must map to predictable reduction above threshold");for(int block=0;block<500;++block){std::fill_n(l,256,0);std::fill_n(r,256,0);e.process(l,r,256,s);}check(e.getDuckReductionDb()<.1,"ducker must release after phrase");}
 {fm::DelayEngine e;e.prepare(48000);fm::Settings s;s.mode=0;s.mix=0;s.duck=1;s.duckThreshold=-12;std::vector<float> original(24000),l(24000),r(24000);for(int i=0;i<24000;++i)original[i]=l[i]=r[i]=.02f*std::sin(i*.13);e.process(l.data(),r.data(),int(l.size()),s);check(e.getDuckReductionDb()<.001,"below-threshold input must not engage ducking");check(l==original,"ducking must not modify dry path");}
 std::cout<<"PASS: transparent Clean; distinct mode bandwidths; oversampled alias rejection; threshold/depth/release ducking; unchanged dry path\n";
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
